import json
with open('/app/resources/treasury_bulletin_1953_03.json', 'r') as f:
    data = json.load(f)

# Search for anything with '12' and '18' 
def search_nested(d, target):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            if target in str(v):
                results.append((k, str(v)[:200]))
            results.extend(search_nested(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(search_nested(item, target))
    return results

results = search_nested(data, '18')
for r in results[:20]:
    print(r)
